CREATE TABLE "IdentityLinkAudit" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "targetUserId" BIGINT NOT NULL,
    "actorUserId" BIGINT,
    "actorType" TEXT NOT NULL DEFAULT 'admin',
    "actorLabel" TEXT,
    "providerIssuer" TEXT NOT NULL,
    "providerSubject" TEXT NOT NULL,
    "evidenceReference" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "IdentityLinkAudit_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "IdentityLinkAudit_actorType_check" CHECK (
      ("actorType" = 'admin' AND "actorUserId" IS NOT NULL AND "actorLabel" IS NULL) OR
      ("actorType" = 'bootstrap' AND "actorUserId" IS NULL AND "actorLabel" IS NOT NULL)
    )
);

CREATE INDEX "IdentityLinkAudit_targetUserId_createdAt_idx" ON "IdentityLinkAudit"("targetUserId", "createdAt");
CREATE INDEX "IdentityLinkAudit_actorUserId_createdAt_idx" ON "IdentityLinkAudit"("actorUserId", "createdAt");

ALTER TABLE "IdentityLinkAudit" ADD CONSTRAINT "IdentityLinkAudit_targetUserId_fkey"
FOREIGN KEY ("targetUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "IdentityLinkAudit" ADD CONSTRAINT "IdentityLinkAudit_actorUserId_fkey"
FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
